import{_ as n,c as s,G as a,J as e,C as t,a4 as p,V as l,b as i,B as r,D as o}from"./chunks/framework.DULpp8DO.js";const c=JSON.parse('{"title":"工具设计的艺术：写给 Agent 的 API 与写给人的 API 有什么不同","description":"Agent 的工具就是它的感官与四肢：从人机 API 消费差异出发，拆解工具描述写法、错误信息设计、粒度权衡、幂等并发与 token 成本，并给出一份工具设计 checklist。","frontmatter":{"title":"工具设计的艺术：写给 Agent 的 API 与写给人的 API 有什么不同","date":"2026-07-25T00:00:00.000Z","categories":["技术分享"],"tags":["Tool Design","function calling","LLM","Agent","API 设计"],"description":"Agent 的工具就是它的感官与四肢：从人机 API 消费差异出发，拆解工具描述写法、错误信息设计、粒度权衡、幂等并发与 token 成本，并给出一份工具设计 checklist。","articleGPT":"工具质量直接决定 agent 的能力上限——工具是智能体的感官和四肢。本文从人与 agent 消费 API 的本质差异讲起（人靠文档加试错，agent 靠工具描述加 schema，一次失败即浪费一轮推理），逐项拆解工具设计的核心议题：如何写\\"何时用/何时不用\\"的工具描述、如何设计可行动的错误信息、合并琐碎工具与拆分大工具的权衡、幂等性与并发安全、schema 常驻上下文的 token 成本，并深入分析 Claude Code 的 Edit 工具 old_string/new_string 设计为何优于行号 patch。文末给出一份可直接套用的工具设计 checklist，适合所有在为 agent 构建 MCP 服务或 function calling 工具的工程师。","cover":"https://lsky.rz15.cn/i/2026/11/19/6afed426bdce1.png","top":null,"share":true,"delete":false,"head":[["link",{"rel":"canonical","href":"https://ruo.ge/posts/2026-07/20260725"}]]},"headers":[],"relativePath":"posts/2026-07/20260725.md","filePath":"posts/2026-07/20260725.md","lastUpdated":1795486093000}');const u=n({name:"posts/2026-07/20260725.md"},[["render",function(n,c,u,d,g,b){const h=l("Mermaid");return i(),s("div",null,[c[1]||(c[1]=a('<h1 id="工具设计的艺术-写给-agent-的-api-与写给人的-api-有什么不同" tabindex="-1">工具设计的艺术：写给 Agent 的 API 与写给人的 API 有什么不同 <a class="header-anchor" href="#工具设计的艺术-写给-agent-的-api-与写给人的-api-有什么不同" aria-label="Permalink to &quot;工具设计的艺术：写给 Agent 的 API 与写给人的 API 有什么不同&quot;">​</a></h1><h2 id="工具是-agent-的感官和四肢" tabindex="-1">工具是 Agent 的感官和四肢 <a class="header-anchor" href="#工具是-agent-的感官和四肢" aria-label="Permalink to &quot;工具是 Agent 的感官和四肢&quot;">​</a></h2><p>一个 agent 能做什么事，不取决于它&quot;知道&quot;什么，而取决于它<strong>能通过工具触达什么、触达得有多精确</strong>。模型再强，没有好工具就像一个天才被绑住手脚关在黑屋子里；而一组设计糟糕的工具，会让强模型表现出弱模型才有的愚蠢——选错工具、传错参数、在报错面前原地打转。</p><p>这就是本文的核心论点：<strong>在 agent 系统中，工具不是功能的附属品，而是能力的天花板。</strong> 同一个模型，接上两套不同质量的工具，表现差距可以大到让人怀疑是换了模型。所以&quot;为 agent 设计工具&quot;是一门独立的手艺，值得像当年&quot;RESTful API 设计&quot;那样被认真对待。</p><h2 id="人和-agent-消费-api-的方式完全不同" tabindex="-1">人和 Agent 消费 API 的方式完全不同 <a class="header-anchor" href="#人和-agent-消费-api-的方式完全不同" aria-label="Permalink to &quot;人和 Agent 消费 API 的方式完全不同&quot;">​</a></h2><p>先想清楚一个根本差异：你的 API 有两类消费者，而他们的&quot;调试手段&quot;天差地别。</p><p><strong>人类开发者</strong>拿到你的 API：读文档、看示例、跑一下、看报错、搜 Stack Overflow、改了再试。人有常识兜底，能容忍含糊的命名和稀烂的报错，试错成本是几分钟。</p><p><strong>Agent</strong> 消费你的工具：它能看到的只有工具的 name、description 和参数 schema——这是它理解工具的<strong>全部</strong>。它没有文档站可逛，没有搜索引擎可问。一次调用失败意味着什么？浪费一整轮推理（几秒到几十秒的延迟 + 一次 API 计费 + 上下文里多一条错误记录），然后它只能依据报错文本盲目重试。</p><p>三个直接的推论：</p><ol><li><strong>工具描述就是 agent 的唯一文档</strong>，必须独立成篇、自包含，不能假设&quot;开发者会去看 README&quot;；</li><li><strong>一次失败的成本极高</strong>，所以工具的报错必须教 agent 下一步怎么改，而不是汇报错误本身；</li><li><strong>工具行为的可预测性大于灵活性</strong>，agent 无法通过&quot;试一试&quot;来理解黑盒行为。</li></ol><h2 id="工具描述怎么写-把-何时用-何时不用-写清楚" tabindex="-1">工具描述怎么写：把&quot;何时用/何时不用&quot;写清楚 <a class="header-anchor" href="#工具描述怎么写-把-何时用-何时不用-写清楚" aria-label="Permalink to &quot;工具描述怎么写：把&quot;何时用/何时不用&quot;写清楚&quot;">​</a></h2><p>Anthropic 在《Writing effective tools for agents》中给出过核心建议，其中最有分量的一条是：<strong>不要只描述工具是什么，要描述什么时候该用、什么时候不该用。</strong></p><p>反面例子（很常见）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>search_docs: 搜索文档库。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>正面例子（Claude Code 风格）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Grep: 基于 ripgrep 的内容搜索工具。</span></span>\n<span class="line"><span>  - 支持完整的正则表达式语法</span></span>\n<span class="line"><span>  - 输出为 file:line:content 格式，带上下文行</span></span>\n<span class="line"><span>  使用时机：当你需要按内容/模式查找代码时（函数定义、字符串常量等）</span></span>\n<span class="line"><span>  不要用于：打开文件看内容（用 Read）；按文件名查找（用 Glob）</span></span>\n<span class="line"><span>  注意：单次输出超过 100 行会被截断，请用更精确的正则缩小范围</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>区别在哪？后者给了模型一个<strong>决策框架</strong>。agent 面对的任务是&quot;在十几个工具里为一个意图选一个&quot;，&quot;何时用/何时不用&quot;恰好就是这个决策的边界条件。特别是相近工具之间（Grep vs Glob、Read vs Bash cat、Edit vs Write），明确写出互斥边界能消除大部分误选。</p><p>其他几条描述规范：</p><ul><li><strong>参数命名自解释</strong>：<code>file_path</code> 优于 <code>path</code>，<code>old_string</code> 优于 <code>s1</code>。agent 是靠名字理解语义的，缩写省下的 token 远抵不上误用的成本；</li><li><strong>在描述里写死约束</strong>：比如&quot;路径必须为绝对路径&quot;&quot;单次最多返回 50 条&quot;，不要指望运行时才报错；</li><li><strong>写清返回值结构</strong>：&quot;返回匹配行数组，每项含 path/line/content 三字段&quot;——agent 要基于返回值决定下一步，返回值结构必须先验可知。</li></ul><h2 id="数量的诅咒-工具越多-选择越差" tabindex="-1">数量的诅咒：工具越多，选择越差 <a class="header-anchor" href="#数量的诅咒-工具越多-选择越差" aria-label="Permalink to &quot;数量的诅咒：工具越多，选择越差&quot;">​</a></h2><p>还有一个容易被忽视的维度：<strong>工具总数影响选择准确率</strong>。多项研究和实践观察都指向同一个结论：候选工具超过一定数量（大致在 15-20 个量级）后，agent 的选择准确率开始明显下滑——描述之间的语义重叠增加，模型在相近候选间摇摆。</p><p>这对 MCP 时代的我们是个提醒：接入三四个 MCP server，工具轻松破 50 个，每一轮推理前全部 schema 常驻上下文。解法有两类：</p><ul><li><strong>做减法</strong>：砍掉重复功能的工具，把高频的参数组合固化成独立工具（如 <code>search_code</code> 取代 <code>search</code> + <code>type=code</code>）；</li><li><strong>动态注入</strong>：按任务阶段或按用户开关加载工具子集，而不是全量常驻。</li></ul><p>工具设计的第一性原理是 token 经济学：<strong>schema 常驻上下文，每个工具每次推理都在付费。</strong> 一个几乎不会被用到的大而全工具，是纯粹的负资产。</p><h2 id="错误信息设计-报错要可行动" tabindex="-1">错误信息设计：报错要可行动 <a class="header-anchor" href="#错误信息设计-报错要可行动" aria-label="Permalink to &quot;错误信息设计：报错要可行动&quot;">​</a></h2><p>给人用的 API，报错追求&quot;信息完整&quot;——stack trace、错误码、内部状态一应俱全。给 agent 用的工具，报错追求<strong>可行动（actionable）</strong>：看完这条报错，agent 应该明确知道下一步怎么改。</p><p>对比一下：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 差：裸报错，agent 只能瞎猜重试</span></span>\n<span class="line"><span>Error: ENOENT</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>// 差：信息多但没给方向</span></span>\n<span class="line"><span>Error: file not found: src/api/handler.ts</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>// 好：告诉 agent 下一步</span></span>\n<span class="line"><span>Error: file not found: src/api/handler.ts</span></span>\n<span class="line"><span>当前目录下相近文件: src/api/handlers.ts, src/api/handler_v2.ts</span></span>\n<span class="line"><span>请确认目标路径后重试，或先用 Glob 搜索。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>第三种报错的关键差别：它把&quot;人类调试时会做的联想&quot;预置进了错误信息里。类似的设计还有很多：</p><ul><li>编辑失败时返回&quot;当前文件最新内容的相关片段&quot;，而不是一句&quot;old_string 不匹配&quot;——agent 看到片段就知道该按什么改；</li><li>参数校验失败时给出 schema 期望的格式示例，而不是只说&quot;参数非法&quot;；</li><li>幂等冲突时返回现有资源的状态，让 agent 可以基于现状做增量决策。</li></ul><p>一条原则：<strong>把每次报错当成一次&quot;教学时机&quot;，而不是一次&quot;事务终止&quot;。</strong> agent 没有老师，报错就是它唯一的老师。</p><h2 id="粒度的权衡-合并琐碎工具-vs-拆分大工具" tabindex="-1">粒度的权衡：合并琐碎工具 vs 拆分大工具 <a class="header-anchor" href="#粒度的权衡-合并琐碎工具-vs-拆分大工具" aria-label="Permalink to &quot;粒度的权衡：合并琐碎工具 vs 拆分大工具&quot;">​</a></h2><p>工具该做多粗还是做多细？两边都有陷阱。</p><p><strong>太琐碎的问题</strong>：一个&quot;create_user / update_user / delete_user / get_user / list_user&quot;式的 REST 风格工具家族，会撑大 schema 开销、增加选择难度，而且常见操作序列（创建后立刻授权）被迫拆成多次调用、多次失败面。</p><p><strong>太粗粒度的问题</strong>：一个万能 <code>manage_project(action, ...)</code> 工具，描述写不清楚，参数组合爆炸，行为不可预测，agent 传错参数的概率飙升，出错后的诊断也困难。</p><p>实践中的收敛点：</p><ol><li><strong>按&quot;心智模型完整性&quot;切分</strong>：一个工具对应 agent 的一项完整意图。<code>create_issue</code> 比 <code>issue(action=&quot;create&quot;)</code> 好，但 <code>create_issue_and_assign</code> 就是过度合并了两个意图；</li><li><strong>高频参数组合可以固化</strong>：如果 agent 总是 A 之后紧跟 B，且 A+B 作为一个原子事务更安全（如&quot;创建文件并写入内容&quot;就该是一个 Write，而不是 create_file + write_content 两步）；</li><li><strong>用参数分化代替工具增殖</strong>：<code>read_file(offset, limit)</code> 一个工具覆盖整读和分页，好于 <code>read_file</code> + <code>read_file_head</code> 两个。</li></ol><p>Claude Code 的工具集是良好示范：十来个工具，每个对应一个清晰意图，参数设计覆盖同一意图下的常见变体。</p><h2 id="幂等性与并发安全" tabindex="-1">幂等性与并发安全 <a class="header-anchor" href="#幂等性与并发安全" aria-label="Permalink to &quot;幂等性与并发安全&quot;">​</a></h2><p>Agent 和人类用户有个行为差异：<strong>agent 会重试，而且重试得很快、很机械。</strong> 你的工具如果没有幂等设计，一次网络抖动后的自动重试就会创建两个重复的工单、发两条重复的消息。</p><p>设计要求：</p><ul><li><strong>写操作尽量幂等</strong>：支持 client 提供的 <code>request_id</code> / 幂等键，同一键重复调用返回同一结果而非重复执行；</li><li><strong>读操作绝对无副作用</strong>：agent 常常&quot;先读确认再写&quot;，读操作若有隐藏副作用（如标记已读、扣积分）会引发诡异 bug；</li><li><strong>明确并发语义</strong>：两个 subagent 并行编辑同一文件是真实会发生的场景。要么加锁并在冲突时报&quot;可行动&quot;错误（&quot;文件正被其他任务编辑，请稍后重试或先读取最新版本&quot;），要么用乐观锁（版本号/内容哈希校验，Claude Code 的 Edit 就内嵌了这一点）；</li><li><strong>高危操作要求显式确认</strong>：删除、发布、付款类操作设计成两段式（dry-run 返回影响面，确认参数后执行），agent 可以先看再动手。</li></ul><h2 id="真实案例-为什么-edit-的-old-string-new-string-优于行号-patch" tabindex="-1">真实案例：为什么 Edit 的 old_string/new_string 优于行号 patch <a class="header-anchor" href="#真实案例-为什么-edit-的-old-string-new-string-优于行号-patch" aria-label="Permalink to &quot;真实案例：为什么 Edit 的 old_string/new_string 优于行号 patch&quot;">​</a></h2><p>早期很多 coding agent 的编辑工具长这样：<code>patch(file, line_start, line_end, new_content)</code>。直觉上很合理——精确、省 token。但实际使用中模型频繁翻车：它数错行号。LLM 对&quot;这是第几行&quot;的感知极不可靠，尤其文件在前面几轮已被修改过之后，行号早已漂移。</p><p>Claude Code 的 Edit 改用了 <code>old_string/new_string</code> 精确替换：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Edit(file_path, old_string, new_string)</span></span>\n<span class="line"><span>  old_string: 文件中将被替换的原文，必须与文件内容逐字符一致（含缩进）</span></span>\n<span class="line"><span>  new_string: 替换后的新文本</span></span>\n<span class="line"><span>  约束：old_string 必须在文件中唯一；不唯一时返回报错并建议扩大上下文范围</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>这个设计的优越之处值得逐条拆：</p><p>一次典型的编辑失败与自愈流程是这样的：</p>',48)),(i(),e(p,null,{default:t((()=>[r(h,{id:"mermaid-220",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20A%20as%20Agent%0A%20%20%20%20participant%20T%20as%20Edit%20%E5%B7%A5%E5%85%B7%0A%20%20%20%20participant%20F%20as%20%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%0A%20%20%20%20A-%3E%3ET%3A%20Edit(old_string%2C%20new_string)%0A%20%20%20%20T-%3E%3EF%3A%20%E8%AF%BB%E5%8F%96%E5%BD%93%E5%89%8D%E6%96%87%E4%BB%B6%E5%86%85%E5%AE%B9%0A%20%20%20%20F--%3E%3ET%3A%20%E6%96%87%E4%BB%B6%E6%9C%80%E6%96%B0%E5%86%85%E5%AE%B9%0A%20%20%20%20alt%20old_string%20%E7%B2%BE%E7%A1%AE%E5%8C%B9%E9%85%8D%E4%B8%94%E5%94%AF%E4%B8%80%0A%20%20%20%20%20%20%20%20T-%3E%3EF%3A%20%E6%89%A7%E8%A1%8C%E6%9B%BF%E6%8D%A2%E5%86%99%E5%85%A5%0A%20%20%20%20%20%20%20%20F--%3E%3ET%3A%20%E5%86%99%E5%85%A5%E6%88%90%E5%8A%9F%0A%20%20%20%20%20%20%20%20T--%3E%3EA%3A%20%E8%BF%94%E5%9B%9E%E6%88%90%E5%8A%9F%E4%B8%8E%E6%9B%B4%E6%96%B0%E5%90%8E%E7%89%87%E6%AE%B5%0A%20%20%20%20else%20%E5%8C%B9%E9%85%8D%E5%A4%B1%E8%B4%A5%E6%88%96%E5%A4%9A%E5%A4%84%E5%8C%B9%E9%85%8D%0A%20%20%20%20%20%20%20%20T--%3E%3EA%3A%20%E6%8A%A5%E9%94%99%20%2B%20%E8%BF%94%E5%9B%9E%E6%96%87%E4%BB%B6%E7%9B%B8%E5%85%B3%E7%89%87%E6%AE%B5%3Cbr%2F%3E%E5%BB%BA%E8%AE%AE%E6%89%A9%E5%A4%A7%20old_string%20%E8%8C%83%E5%9B%B4%0A%20%20%20%20%20%20%20%20A-%3E%3ET%3A%20%E4%BF%AE%E6%AD%A3%E5%90%8E%E9%87%8D%E6%96%B0%20Edit%EF%BC%88%E4%B8%8B%E4%B8%80%E8%BD%AE%EF%BC%89%0A%20%20%20%20end%0A"})])),fallback:t((()=>c[0]||(c[0]=[o(" Loading... ")]))),_:1})),c[2]||(c[2]=a('<p>逐条拆解其优越性：</p><ol><li><strong>用模型的长板规避短板</strong>。复制原文是语言模型的强项（逐 token 已在上下文里），数行号是弱项。设计工具时应该让模型用长板干活；</li><li><strong>天然防错</strong>。old_string 匹配失败说明模型对文件现状的理解有误——这恰好是最该被拦住的错误。匹配成功则意味着&quot;模型看到的世界&quot;和&quot;真实世界&quot;是一致的，编辑是建立在正确认知上的。行号 patch 则没有这层校验：行号错了照样改，改的就是错的地方；</li><li><strong>失败即教学</strong>。匹配失败时返回文件当前的相关片段，模型立刻自我修正，通常下一轮就成功；</li><li><strong>内容寻址天然抗漂移</strong>。多次编辑之间行号全在变，但内容锚点不受影响。</li></ol><p>反面教材是&quot;唯一性&quot;这个约束暴露的问题：文件里有多处相同片段时 Edit 会拒绝执行。但注意它的报错设计——提示&quot;把更多上下文包进 old_string 使其唯一&quot;，这就把失败转化成了下一步的指引，正好呼应前文的可行动报错原则。</p><h2 id="给工具设计者的-checklist" tabindex="-1">给工具设计者的 Checklist <a class="header-anchor" href="#给工具设计者的-checklist" aria-label="Permalink to &quot;给工具设计者的 Checklist&quot;">​</a></h2><p>为 agent 设计工具时，逐项过一遍：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>理解成本</span></span>\n<span class="line"><span>  [ ] name 是动词短语，自解释，无缩写歧义</span></span>\n<span class="line"><span>  [ ] description 独立自包含，不依赖外部文档</span></span>\n<span class="line"><span>  [ ] 写明了&quot;何时用&quot;和&quot;何时不用&quot;，与相近工具划清边界</span></span>\n<span class="line"><span>  [ ] 参数名自解释，必填项最少化，描述里带格式示例</span></span>\n<span class="line"><span>  [ ] 返回值结构在描述中先验可知</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>行为设计</span></span>\n<span class="line"><span>  [ ] 报错可行动：包含原因 + 下一步建议（相近资源、正确格式示例）</span></span>\n<span class="line"><span>  [ ] 读操作无副作用，写操作幂等（支持幂等键）</span></span>\n<span class="line"><span>  [ ] 并发冲突有明确语义和可行动的报错</span></span>\n<span class="line"><span>  [ ] 高危操作支持 dry-run / 两段式确认</span></span>\n<span class="line"><span>  [ ] 长输出自动截断或落盘，绝不打穿上下文</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>成本与规模</span></span>\n<span class="line"><span>  [ ] schema 紧凑：无冗余字段，描述控制在几百 token 内</span></span>\n<span class="line"><span>  [ ] 工具总数有意识控制（接近 20 个时做合并或动态加载）</span></span>\n<span class="line"><span>  [ ] 不存在&quot;几乎不会被调用&quot;的大而全工具</span></span>\n<span class="line"><span>  [ ] 参数用枚举/格式约束收窄，减少模型自由发挥的空间</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>可演化性</span></span>\n<span class="line"><span>  [ ] 工具行为变化时，description 同步更新（agent 的&quot;文档&quot;就是 schema）</span></span>\n<span class="line"><span>  [ ] 返回值结构保持向后兼容，新增字段只增不改语义</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>回到开头的比喻：工具是 agent 的感官和四肢。设计感官时问&quot;它能不能可靠地感知&quot;，设计四肢时问&quot;它能不能精确地行动，失败了知不知道怎么纠正&quot;。判断一套工具好不好，有个简单的测试方法：把工具描述丢给一个从没见过你系统的 agent，看它能否在一次会话内、零人工干预地正确完成任务。能，说明你的工具&quot;会说话&quot;；不能，看它卡在哪一步——那一步就是你描述或报错的缺陷所在。为 agent 设计工具，本质上是把对人类开发者的所有体贴（好文档、好报错、好默认值），压缩进几百 token 的 schema 里，再乘以它在整个系统里被调用一万次的频次。</p>',8))])}]]);export{c as __pageData,u as default};
